#!/usr/bin/env python3
# patch-158-F: empty-state entry point for multi-asset view
"""
Fix the chicken-and-egg in 158-D where the multi-asset view only
rendered when assets were already attached, but users had no UI to
attach the first one.

Change:
  - AppointmentController::show now branches to multi-asset view
    whenever tenant has multi_asset_enabled (drops the "must have
    at least one asset" requirement).
  - show-multi-asset.blade.php gains an empty-state block: when no
    assets are attached, renders a dashed callout with a working
    "+ Attach asset" button as the entry point.
  - The bottom "+ Attach asset to this appointment" button is hidden
    when the empty state is showing (otherwise we have two buttons
    doing the same thing).

Caveat: this means tenants with multi_asset_enabled=true who have
existing single-asset appointments will now see those appointments
in the multi-asset view (with the empty state) instead of the legacy
view. Their existing items/addons will appear in the "Unassigned
services" card at the bottom. They can attach an asset and pin
services to it from there. Acceptable trade-off in exchange for
eliminating the entry-point problem.

Standalone Python. Idempotent.
"""
